# Factorial recursivo
def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

print("5! =", factorial(5))
print("10! =", factorial(10))

# Fibonacci recursivo (ineficiente)
def fib(n):
    if n <= 1:
        return n
    return fib(n - 1) + fib(n - 2)

print("\nFibonacci:")
for i in range(8):
    print(f"  fib({i}) = {fib(i)}")
